async function T(p,s,x,y,size,style,c,opts={}){const t=figma.createText();t.fontName={family:'Urbanist',style};t.characters=s;t.fontSize=size;t.fills=[sol(c)];if(opts.lh)t.lineHeight={value:opts.lh,unit:'PERCENT'};if(opts.w){t.textAutoResize='HEIGHT';t.resize(opts.w,10);}t.x=x;t.y=y;if(opts.align)t.textAlignHorizontal=opts.align;p.appendChild(t);return t;}
function R(p,x,y,w,h,fill,r=0,sc){const n=figma.createRectangle();n.x=x;n.y=y;n.resize(w,h);n.fills=fill?[sol(fill)]:[];if(r)n.cornerRadius=r;if(sc){n.strokes=[sol(sc)];n.strokeWeight=1;}p.appendChild(n);return n;}
function FR(p,x,y,w,h,fill,r=0,sc){const n=figma.createFrame();n.x=x;n.y=y;n.resize(w,h);n.fills=fill?[sol(fill)]:[];if(r)n.cornerRadius=r;if(sc){n.strokes=[sol(sc)];n.strokeWeight=1;}n.clipsContent=false;p.appendChild(n);return n;}
async function IC(id,p,x,y,size=24,color){const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();p.appendChild(i);if(size!==24){const s=size/Math.max(i.width,i.height);i.rescale(s);}i.x=x;i.y=y;if(color){for(const v of i.findAll(n=>'VECTOR|BOOLEAN_OPERATION|ELLIPSE|RECTANGLE|LINE|STAR|POLYGON'.includes(n.type))){try{v.fills=[sol(color)];v.strokes=[sol(color)];}catch(e){}}}return i;}
async function CV(id,p,x,y,w,h,r=12){const f=figma.createFrame();f.name='cover';f.x=x;f.y=y;f.resize(w,h);f.cornerRadius=r;f.clipsContent=true;f.fills=[sol(SURF2)];p.appendChild(f);const c=await figma.getNodeByIdAsync(id);const i=c.createInstance();f.appendChild(i);const s=Math.max(w/i.width,h/i.height);i.rescale(s);i.x=(w-i.width)/2;i.y=(h-i.height)/2;return f;}
function link(node,dest){if(node.id===dest)return;node.reactions=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:null}]}];}
